test("actor circuit opens after maxConsecutiveRefusals and stops before maxRounds with no verified candidate", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  let dispatchCalls = 0;
  const dispatch = async (jobs) => {
    dispatchCalls += 1;
    return jobs.map((job) => ({ id: job.id, refusal: { type: "no-feasible-endpoint" }, attempts: [] }));
  };
  const result = await runMission({
    id: "urn:test:mission:circuit-breaker",
    objective: "Repair the add function so the declared test passes.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 1,
    maxRounds: 5,
    maxConsecutiveRefusals: 2,
    apply: false,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, false);
  assert.equal(result.outcome.classification, "unresolved");
  assert.equal(result.metrics.verifiedCandidates, 0);
  assert.equal(dispatchCalls, 2);
  assert.equal(result.metrics.rounds, 2);
  assert.equal(result.actors[0].status, "refused");
});"}]},"reason":"Add circuit-breaker test: dispatch returns refusal records, maxConsecutiveRefusals=2 < maxRounds=5, asserts exactly 2 dispatch calls and actor status refused with no verified candidate"}]},{"similarity":0.30884310026970785,"objective":"Add a deterministic test to test/mission-runtime.test.mjs proving that one valid actor action resets consecutiveRefusals: inject a refusal, then a valid read action, then another refusal, then a valid edit that passes verification. With maxConsecutiveRefusals set to 2, assert the actor remains eligible after the separated refusals and ultimately produces a verified candidate.

